import React, { useState } from 'react';
import { Link } from 'react-router-dom';

const RequestCall = () => {

    const [name, setName] = useState('');
    const [mobile, setMobile] = useState('');

    const handleNameChange = (e) => {
        setEmail(e.target.value);
    };

    const handleMobileChange = (e) => {
        setPassword(e.target.value);
    };


    const handleSubmitLogin = (e) => {
        e.preventDefault();

        if (email === "") return alert("Enter your email");
        if (password === "") return alert("Enter your password");
        console.log('Form submitted:', { email, password });

        setName('');
        setMobile('');
    };


    return (
        <div className='fixed bottom-[10px]'>

            <div className='w-[300px] sm:w-[500px] md:w-[650px] py-10 rounded-xl bg-black bg-opacity-80'>

                <div className='mb-10 text-white text-[30px] text-center font-bold'>Request a call back</div>

                <form className="flex flex-col items-center justify-center space-y-5" onSubmit={handleSubmitLogin}>

                    <div className="flex flex-col space-y-2 w-[250px] sm:w-[400px] md:w-[600px]">
                        <input className="px-2 sm:px-5 py-1 sm:py-2 text-black text-md rounded-lg sm:rounded-xl outline-0 placeholder-gray-400 placeholder:italic placeholder:text-sm" type="text" value={name} onChange={handleNameChange} placeholder='Enter your name' required />
                    </div>

                    <div className="flex flex-col space-y-2 w-[250px] sm:w-[400px] md:w-[600px]">
                        <input className="px-2 sm:px-5 py-1 sm:py-2 text-black text-md rounded-lg sm:rounded-xl outline-0 placeholder-gray-400 placeholder:italic placeholder:text-sm" type="text" value={mobile} onChange={handleMobileChange} placeholder='Enter your Mobile' required />
                    </div>

                    <button type='submit' className='p-2 text-black rounded-lg text-lg hover:scale-105 duration-300' style={{ color: 'white', fontWeight: '500', backgroundColor: 'rgba(255, 0, 0, 1)', }}>
                        Submit call request
                    </button>

                </form>
            </div>

        </div>
    );
};

export default RequestCall;
